    author: "Smit-Prajapati",
    source: "galaxy",
    html: "<input class=\"checkbox\" type=\"checkbox\">",
    css: "/* From Uiverse.io by Smit-Prajapati - Tags: checkbox, cool checkbox, check */\n.checkbox {\n  appearance: none;\n  width: 30px;\n  aspect-ratio: 1;\n  border-radius: 8px;\n  border: 2px solid black;\n  position: relative;\n  transition: all 0.2s ease-in-out;\n}\n\n.checkbox::before {\n  font-family: \"Quicksand\", sans-serif;\n  position: absolute;\n  bottom: -4px;\n  left: 1px;\n  content: \"\u2714\";\n  font-size: 40px;\n  color: rgb(255, 153, 0);\n  transform: scale(0);\n  transition: all 0.2s ease-in-out;\n}\n\n.checkbox:checked::before {\n  animation: zoom 0.5s ease-in-out;\n  transform: scale(1);\n}\n\n@keyframes zoom {\n  0% {\n    transform: scale(0);\n  }\n\n  20% {\n    transform: scale(1.5);\n  }\n\n  40% {\n    transform: scale(0.5);\n  }\n\n  50% {\n    transform: scale(1);\n  }\n\n  70% {\n    transform: scale(1.2);\n  }\n\n  90% {\n    transform: scale(0.8);\n  }\n\n  100% {\n    transform: scale(1);\n  }\n}",
