    author: "talhaabu1",
    source: "galaxy",
    html: "<div class=\"checkbox-wrapper-23\">\n  <input type=\"checkbox\" id=\"check-23\">\n  <label for=\"check-23\" style=\"--size: 30px\">\n    <svg viewBox=\"0,0,50,50\">\n      <path d=\"M5 30 L 20 45 L 45 5\"></path>\n    </svg>\n  </label>\n</div>",
