    html: "<label class=\"checkbox\">\n  <input class=\"checkbox-input\" type=\"checkbox\" />\n  <svg class=\"checkbox-check\" width=\"28\" height=\"28\">\n    <polyline points=\"20 6 9 17 4 12\"></polyline>\n  </svg>\n</label>",
